 	const params = (inter?.params && typeof inter.params === "object") ? inter.params : null;
 	const charges = Number(params?.chargesRemaining);
 	if (Number.isFinite(charges) && charges <= 0 && !rec.tags.includes("inactive")) {
 		rec.tags.push("inactive");
 	}
 }
+
+function pushTag(rec, tag) {
+	if (!rec.tags.includes(tag)) rec.tags.push(tag);
+}
+
+function projectAtmosphericTags(world, id, rec) {
+	const flame = world.get(id, FlameSource);
+	if (flame && flame.active !== false) {
+		pushTag(rec, `flame:${String(flame.fuel || "candle").toLowerCase()}`);
