import { defineComponent } from "../../lib/ecs-js/index.js";

/**
 * Physical flame-bearing decor. Display decides how each fuel reads visually.
 */
export const FlameSource = defineComponent(
  "FlameSource",
  {
    fuel: "candle",
    active: true,
  },
  {
    validate(rec) {
      return typeof rec.fuel === "string" && rec.fuel.length > 0;
    },
  },
);

/**
 * Living or mineral growth that naturally glows.
 */
export const Bioluminescent = defineComponent(
  "Bioluminescent",
  {
    species: "glowcap",
    active: true,
  },
  {
    validate(rec) {
      return typeof rec.species === "string" && rec.species.length > 0;
    },
  },
);

/**
 * Sacred or profane ritual focus. Aspect is domain meaning, not render data.
 */
export const RitualFocus = defineComponent(
  "RitualFocus",
  {
    aspect: "holy",
    active: true,
  },
  {
    validate(rec) {
      return typeof rec.aspect === "string" && rec.aspect.length > 0;
    },
  },
);

/**
 * Surface or fixture that catches nearby light.
 */
export const ReflectiveSurface = defineComponent(
  "ReflectiveSurface",
  {
    material: "iron",
    polish: 1,
  },
  {
    validate(rec) {
      return (
        typeof rec.material === "string" &&
        rec.material.length > 0 &&
        typeof rec.polish === "number"
      );
    },
  },
);

/**
 * Dungeon machinery that marks pressure, vapor, drainage, or moving water.
 */
export const HydraulicAtmosphere = defineComponent(
  "HydraulicAtmosphere",
  {
    role: "vent",
    active: true,
  },
  {
    validate(rec) {
      return typeof rec.role === "string" && rec.role.length > 0;
    },
  },
);

/**
 * Physical corruption, cursed stone, or a void scar that swallows surrounding light.
 */
export const VoidTaint = defineComponent(
  "VoidTaint",
  {
    source: "rift",
    active: true,
  },
  {
    validate(rec) {
      return typeof rec.source === "string" && rec.source.length > 0;
    },
  },
);

